+{
+    $query = 'select * from ' . NEWSLETTER_USERS_TABLE . " where status='C'";
+    $known = array_keys(deliveryLists());
+    $where = [];
+    foreach ($lists as $list) {
+        $list = (int) $list;
+        if (in_array($list, $known, true)) {
