+/** Text of a list of blocks, without markup. */
+function blocksText(array $blocks): string
+{
+    $text = '';
+    foreach ($blocks as $block) {
+        $text .= ' ' . wp_strip_all_tags(render_block($block));
+    }
+
+    return trim((string) preg_replace('/\s+/', ' ', $text));
