+function issueLeadText(\WP_Post $post): string
+{
+    $sections = sections($post);
+    if (count($sections) !== 4) {
+        return '';
+    }
+
+    foreach ($sections['front']['innerBlocks'] as $child) {
+        if (str_contains((string) ($child['attrs']['className'] ?? ''), 'opn-story')) {
